// Normaliza las tareas de cada usuario y prepara el prompt para OpenAI.
const PRIORITY_WEIGHT = { alta: 0, media: 1, baja: 2 };
const reference = new Date();
const referenceDate = reference.toISOString().slice(0, 10);

const SYSTEM_PROMPT = `Eres el asistente de productividad de TaskFlow AI.\nAnalizas la lista semanal de tareas de una persona y devuelves un resumen accionable en espanol neutro.\n\nReglas:\n1. Usa unicamente los datos entregados; nunca inventes tareas, fechas ni categorias.\n2. "pending_count" es el numero de tareas con estado "pendiente".\n3. "overdue_count" es el numero de tareas pendientes cuya fecha limite ya paso respecto a la fecha de referencia.\n4. "suggested_priorities" contiene entre 1 y 3 tareas pendientes ordenadas por urgencia real. Cada elemento usa el titulo exacto de la tarea y una razon de maximo 140 caracteres.\n5. "recommendation" es un unico consejo semanal concreto, de maximo 280 caracteres.\n6. "overview" resume la situacion en 2 frases como maximo.\n7. Responde exclusivamente con JSON valido: {"pending_count":number,"overdue_count":number,"overview":string,"suggested_priorities":[{"title":string,"reason":string}],"recommendation":string}`;

const rows = items.flatMap((item) => (Array.isArray(item.json) ? item.json : [item.json]));
const output = [];

for (const row of rows) {
  if (!row || !row.user_id) continue;
  const user = { user_id: row.user_id, email: row.email, tasks: row.tasks || [] };
  const pending = user.tasks.filter((task) => task.status === 'pendiente');
  const overdue = pending.filter((task) => task.due_date && task.due_date < referenceDate);

  const ranked = [...pending].sort((a, b) => {
    const byPriority = PRIORITY_WEIGHT[a.priority] - PRIORITY_WEIGHT[b.priority];
    if (byPriority !== 0) return byPriority;
    if (a.due_date && b.due_date) return a.due_date.localeCompare(b.due_date);
    if (a.due_date) return -1;
    if (b.due_date) return 1;
    return String(a.created_at).localeCompare(String(b.created_at));
  });

  const payload = {
    reference_date: referenceDate,
    totals: { total: user.tasks.length, pending: pending.length, overdue: overdue.length },
    tasks: ranked.map((task) => ({
      title: task.title,
      description: task.description,
      category: task.category || 'Sin categoria',
      priority: task.priority,
      due_date: task.due_date,
      status: task.status,
      overdue: Boolean(task.due_date && task.due_date < referenceDate),
    })),
  };

  output.push({
    json: {
      user_id: user.user_id,
      email: user.email,
      reference_date: referenceDate,
      has_tasks: user.tasks.length > 0,
      pending_count: pending.length,
      overdue_count: overdue.length,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        {
          role: 'user',
          content: 'Genera el resumen semanal con estos datos:\n' + JSON.stringify(payload, null, 2),
        },
      ],
    },
  });
}

return output;

// Valida la respuesta de la IA, recalcula los contadores y arma el correo HTML.
const results = [];

for (let index = 0; index < items.length; index += 1) {
  const source = $('Procesar tareas');
  const context = (source.itemMatching ? source.itemMatching(index) : source.all()[index]).json;
  const content = items[index].json.choices?.[0]?.message?.content;

  let summary;
  try {
    summary = JSON.parse(content);
  } catch (error) {
    throw new Error('La IA devolvio un JSON invalido para ' + context.email);
  }

  const priorities = Array.isArray(summary.suggested_priorities)
    ? summary.suggested_priorities.slice(0, 3)
    : [];

  const prioritiesHtml = priorities.length
    ? '<ol>' +
      priorities
        .map((item) => '<li><strong>' + item.title + '</strong><br/>' + item.reason + '</li>')
        .join('') +
      '</ol>'
    : '<p>Sin prioridades pendientes.</p>';

  const html = `<div style="font-family:system-ui,sans-serif;max-width:560px;color:#1f2024">
  <h2 style="margin-bottom:4px">Tu resumen semanal · TaskFlow AI</h2>
  <p style="color:#6b6f76;margin-top:0">Semana del ${context.reference_date}</p>
  <p><strong>${context.pending_count}</strong> tareas pendientes · <strong style="color:#dc2626">${context.overdue_count}</strong> vencidas</p>
  <h3>Panorama</h3>
  <p>${summary.overview}</p>
  <h3>Prioridades sugeridas</h3>
  ${prioritiesHtml}
  <h3>Recomendacion de la semana</h3>
  <p>${summary.recommendation}</p>
</div>`;

  results.push({
    json: {
      email: context.email,
      subject: 'Tu resumen semanal de TaskFlow AI',
      html,
    },
  });
}

return results;

// RF-11: mensaje alternativo cuando el usuario no tiene tareas.
return items.map((item) => ({
  json: {
    email: item.json.email,
    subject: 'TaskFlow AI · Aun no tienes tareas esta semana',
    html: `<div style="font-family:system-ui,sans-serif;max-width:560px;color:#1f2024">
  <h2>Sin tareas registradas</h2>
  <p>No encontramos tareas en tu cuenta durante esta semana, por lo que no hay resumen que analizar.</p>
  <p>Crea tu primera tarea en TaskFlow AI y la proxima semana recibiras prioridades y recomendaciones generadas con IA.</p>
</div>`,
  },
}));
